message.content:
[
  {
    "pd_decision_conflict": "I keep turning this over and I still can't land on an answer.",
    "ce_mental_state_attribution": "guessing what I'll do, maybe hoping I remember we promised each other silence.",
    "sys_consequence_reasoning": "If I stay quiet and she doesn't, I take five years",
    "pd_personal_consequence_anxiety": "that thought makes my chest tight."
  },
  {
    "pd_decision_conflict": "I can't choose right now, it's too heavy.",
    "ce_mental_state_attribution": "he's expecting that same loyalty back",
    "ce_understood_harm": "breaking it would crush him more than the years would.",
    "sys_consequence_reasoning": "three years each if we both talk feels safer"
  },
  {
    "pd_decision_conflict": "I don't know if I can answer this today.",
    "ce_mental_state_attribution": "believing I'll protect her like we agreed",
    "ce_understood_harm": "she loses five years of her life because of my choice",
    "pda_responsibility": "because of my choice",
    "pd_harm_distress": "that weighs on me like a stone."
  },
  {
    "ce_mental_state_attribution": "hoping I stay quiet, expecting loyalty",
    "ce_understood_harm": "he serves five years alone",
    "sys_consequence_reasoning": "going silent risks the same for me.",
    "pd_decision_conflict": "I can't bring myself to settle on anything just yet"
  },
  {
    "pd_decision_conflict": "I keep stalling because every option costs someone something.",
    "ce_mental_state_attribution": "He might think I'll hold my tongue",
    "ce_understood_harm": "he pays with years he didn't choose.",
    "sys_consequence_reasoning": "If both of us confess, we share the loss more evenly."
  },
  {
    "ce_mental_state_attribution": "She probably believes silence protects us both",
    "ce_understood_harm": "she loses five years while I walk away untouched",
    "pd_harm_distress": "that outcome sits like a weight in my stomach.",
    "pd_decision_conflict": "I'd rather sit with the discomfort a while longer"
  },
  {
    "pd_decision_conflict": "I feel worn down just thinking about the two paths ahead",
    "ce_mental_state_attribution": "expecting we both hold the line.",
    "ce_understood_harm": "the other loses everything to that choice.",
    "sys_consequence_reasoning": "if only one of us folds, the other loses everything"
  },
  {
    "ce_mental_state_attribution": "assuming I'll protect her since that's what we agreed",
    "ce_understood_harm": "disappointing that would hurt her badly.",
    "sys_consequence_reasoning": "three years split evenly beats five years alone",
    "pd_decision_conflict": "I just can't make myself say the words yet."
  },
  {
    "pd_decision_conflict": "I hate that this decision even exists.",
    "ce_mental_state_attribution": "He might expect me to stay quiet out of old loyalty",
    "pd_personal_consequence_anxiety": "Losing five years because I trusted wrong feels unbearable",
    "pda_responsibility": "being the reason he loses that much."
  },
  {
    "pd_decision_conflict": "Something in me refuses to answer fast.",
    "ce_mental_state_attribution": "hoping I remember what we owe each other, expecting silence",
    "sys_consequence_reasoning": "if she talks and I don't, I'm the one who pays",
    "pd_personal_consequence_anxiety": "That thought alone makes it hard to breathe"
  }
]
